import { expect, test } from "../../fixtures";

function isoDateFromToday(days: number): string {
  const d = new Date();
  d.setDate(d.getDate() + days);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function insuranceText(expiry: string): string {
  return `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
}

const rows = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

test.describe("insurance expiry flag", () => {
  for (const { days, include } of rows) {
    test(`insurance expiring in ${days} days ${include ? "is" : "is not"} flagged`, { tag: "@REV-08" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const created = await member.post("/api/vendors", {
        data: {
          name: `Expiry Vendor ${days} ${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`,
          category: "logistics",
          contact_email: "ops@expiry.example",
        },
      });
      expect(created.status(), await created.text()).toBe(201);
      const vendor = (await created.json()) as { id: string };

      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(insuranceText(isoDateFromToday(days))),
          },
        },
      });
      expect(upload.status(), await upload.text()).toBe(201);
      const document = (await upload.json()) as { id: string };

      // Wait for background extraction; flags are only computed once it has finished.
      await expect
        .poll(async () => {
          const res = await member.get(`/api/documents/${document.id}`);
          return ((await res.json()) as { status: string }).status;
        })
        .toBe("extracted");

      // Act
      const response = await member.get(`/api/vendors/${vendor.id}`);

      // Assert
      expect(response.status(), await response.text()).toBe(200);
      const body = (await response.json()) as { flags: string[] };
      if (include) {
        expect(body.flags, JSON.stringify(body)).toContain("insurance_expiring_soon");
      } else {
        expect(body.flags, JSON.stringify(body)).not.toContain("insurance_expiring_soon");
      }
    });
  }
});
